import{_ as t,c as r,o as s,ah as i,j as e,a}from"./chunks/framework.oAolcYhj.js";const d="/Qonnectra-docs/pr-14/images/manual/teil-a/map.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail_select.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/map_opacity.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend_actions.jpg",g="/Qonnectra-docs/pr-14/images/manual/teil-a/map_selected_object.jpg",m="/Qonnectra-docs/pr-14/videos/map_attachment.webm",b="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search.jpg",p="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search_flow.jpg",D=JSON.parse('{"title":"5. Karte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/05-karte.md","filePath":"manual/teil-a-anwenderhandbuch/05-karte.md"}'),k={name:"manual/teil-a-anwenderhandbuch/05-karte.md"};function f(S,n,z,_,K,A){return s(),r("div",null,[...n[0]||(n[0]=[i('<h1 id="_5-karte" tabindex="-1">5. Karte <a class="header-anchor" href="#_5-karte" aria-label="Permalink to &quot;5. Karte&quot;">​</a></h1><p>Die Karte ist eines der zentralen Werkzeuge in Qonnectra. Sie dient der visuellen Darstellung des Netzbestands, der Orientierung im Raum und dem schnellen Aufruf von Informationen zu einzelnen Netzobjekten. Sie erreichen die Karte über die linke Navigation durch Klicken auf den Menüpunkt „Karte“.</p><p><img src="'+d+'" alt="Screenshot Karte" data-zoomable="true"></p><p>Solange kein Objekt ausgewählt ist, erscheint unten in der Karte der Hinweis „Klicken Sie auf einen Layer um das Objekt abzufragen.“ Er verschwindet, sobald Sie ein Objekt anklicken.</p><h2 id="_5-1-bewegung-in-der-karte" tabindex="-1">5.1 Bewegung in der Karte <a class="header-anchor" href="#_5-1-bewegung-in-der-karte" aria-label="Permalink to &quot;5.1 Bewegung in der Karte&quot;">​</a></h2><p>Sie können in der Karte auf verschiedene Arten navigieren: Zoomen Sie mit dem Mausrad oder dem Touchpad hinein und heraus. Verschieben Sie den Kartenausschnitt mit gedrückter linker Maustaste.</p><p>Wenn Sie bei geöffneter Karte ein anderes Projekt auswählen, springt die Karte nicht automatisch in dessen Gebiet. Um dorthin zu gelangen, klicken Sie in der Legende oben rechts beim Eintrag „Adresse“ auf das Lupensymbol „Auf Ausdehnung zoomen“. Damit navigiert die Ansicht in den Bereich, in dem für dieses Projekt Daten vorhanden sind.</p><p class="img-row"><img src="'+l+'" alt="Screenshot Karte mit Hervorhebung des Layers Adresse in der Legende rechts oben" data-zoomable="true"><img src="'+o+'" alt="Screenshot Karte nach dem Zoom auf die Ausdehnung des Layers Adresse" data-zoomable="true"></p><p>Hinweis: Qonnectra merkt sich den letzten Kartenausschnitt. Wenn Sie die Karte erneut öffnen, sehen Sie wieder die Stelle, an der Sie zuletzt gearbeitet haben.</p><h2 id="_5-2-anpassung-der-darstellung" tabindex="-1">5.2 Anpassung der Darstellung <a class="header-anchor" href="#_5-2-anpassung-der-darstellung" aria-label="Permalink to &quot;5.2 Anpassung der Darstellung&quot;">​</a></h2><p>Links unten in der Kartenansicht finden Sie den Regler „Transparenz“, mit dem Sie die <strong>Transparenz</strong> der Hintergrundkarte anpassen können. Der aktuelle Wert steht als Prozentangabe rechts neben der Bezeichnung. Dies ist hilfreich, um Netzdaten besser sichtbar zu machen.</p><p><img src="'+h+'" alt="Screenshot Karte mit Hervorhebung des Schiebereglers für die Transparenz der Karte" data-zoomable="true"></p><p>Auf der rechten Seite befindet sich die <strong>interaktive Legende</strong> („Layer“-Menü) mit den Einträgen „Adresse“, „Netzknoten“, „Trasse“, „Rohr“, „Gebiet“ und „OpenStreetMap“. Über die Symbole an den Einträgen können Sie:</p><ul><li>Objektarten (Layer) ein- oder ausblenden („Layer anzeigen“ bzw. „Layer ausblenden“)</li><li>Beschriftungen anzeigen oder verbergen („Beschriftungen anzeigen“ bzw. „Beschriftungen ausblenden“)</li><li>Mit „Auf Ausdehnung zoomen“ die Ansicht auf alle Objekte eines Layers ausrichten</li><li>Layergruppen über den kleinen Pfeil links am Eintrag ein- oder ausklappen</li><li>Die Hintergrundkarte über den Eintrag „OpenStreetMap“ ausblenden oder in den Dunkelmodus wechseln</li></ul><p>Nicht jeder Eintrag bietet alle Möglichkeiten. Beim Eintrag „Rohr“ steht ausschließlich die Schaltfläche „Leitungsbeschriftungen anzeigen“ zur Verfügung. Ausklappen lassen sich standardmäßig die Einträge „Netzknoten“ und „Gebiet“ – dort sehen Sie die einzelnen Typen und können sie einzeln ein- und ausblenden.</p><p>Wichtig: Beschriftungen werden erst ab einer ausreichenden Zoomstufe eingeblendet. Wenn sich nach dem Einschalten nichts sichtbar ändert, zoomen Sie weiter in die Karte hinein.</p><p>Über der Legende können Sie mit dem Pfeil links neben „Layer“ die gesamte Liste einklappen, wenn Sie mehr von der Karte sehen möchten.</p><p class="img-row"><img src="'+c+'" alt="Screenshot Karte mit Hervorhebung der Legende oben rechts" data-zoomable="true"><img src="'+u+'" alt="Vier Screenshots der Karte mit verschiedenen Einstellungen in der Legende" data-zoomable="true"></p><h2 id="_5-3-auswahl-von-objekten" tabindex="-1">5.3 Auswahl von Objekten <a class="header-anchor" href="#_5-3-auswahl-von-objekten" aria-label="Permalink to &quot;5.3 Auswahl von Objekten&quot;">​</a></h2><p>Wenn Sie ein Objekt (z. B. eine Trasse oder einen Netzknoten) auf der Karte anklicken, öffnet sich auf der rechten Seite eine Detailanzeige. Diese <strong>Info-Box</strong> überlagert die Karte, ohne den Kartenausschnitt zu verändern.</p><p>Die Reiter der Info-Box stehen untereinander am linken Rand der Box. Welche Reiter angezeigt werden, hängt von der Objektart ab:</p><ul><li>Trasse: „Eigenschaften“, „Rohrübersicht“, „Kabelübersicht“, „Aktionen“, „Anhänge“</li><li>Netzknoten: „Eigenschaften“, „Aktionen“, „Anhänge“</li><li>Adresse: „Eigenschaften“, „Aktionen“, „Anhänge“</li><li>Gebiet: „Eigenschaften“, „Anhänge“</li></ul><p>Die Angaben im Reiter „Eigenschaften“ sind nicht bearbeitbar, sondern dienen als Informationsquelle. Der Reiter „Rohrübersicht“ zeigt die Rohre der Trasse, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>, „Kabelübersicht“ die darin liegenden Kabel.</p><p>Im Reiter „Aktionen“ finden Sie weiterführende Ansichten zum ausgewählten Objekt, etwa „Grabenprofil anzeigen“ bei einer Trasse oder „Slot-Konfiguration anzeigen“, „Struktur anzeigen“ und „Folgen“ bei einem Netzknoten. Bearbeiten können Sie ausschließlich den Reiter „Anhänge“ – die Informationen dazu entnehmen Sie dem Abschnitt <a href="#_5-3-1-anhange-von-kartenobjekten">Anhänge von Kartenobjekten</a>.</p><p>Sobald Sie ein anderes Objekt auswählen, ändern sich die Einträge in der Info-Box entsprechend dem selektierten Element.</p><p>Sie können die Info-Box über das Kreuz „Seitenleiste schließen“ oben rechts in der Box schließen. Alternativ heben Sie die Auswahl auf, indem Sie in einen Bereich der Karte klicken, der kein Element enthält. Das ist innerhalb eines Projektgebiets allerdings kaum möglich, weil dessen Fläche die gesamte Umgebung überdeckt – in diesem Fall ist das Kreuz der schnellere Weg. Wenn Sie die Auswahl dennoch per Klick aufheben möchten, zoomen Sie aus der Karte heraus und klicken Sie in einen Bereich außerhalb des Elements.</p><p>Ist die Info-Box zu schmal, ziehen Sie sie am linken Rand über den Griff „Größe der Seitenleiste ändern“ breiter.</p><p><img src="'+g+'" alt="Screenshot Karte mit Hervorhebung eines ausgewählten Objekts und der Anzeige der Details in einer Info-Box rechts" data-zoomable="true"></p><p>Hinweis: Wenn Sie ein Objekt über die Suche auswählen, öffnet sich die Info-Box <strong>nicht</strong>. Die Karte springt dann nur an die passende Stelle. Um die Details zu sehen, klicken Sie das Objekt anschließend in der Karte an.</p><h3 id="_5-3-1-anhange-von-kartenobjekten" tabindex="-1">5.3.1 Anhänge von Kartenobjekten <a class="header-anchor" href="#_5-3-1-anhange-von-kartenobjekten" aria-label="Permalink to &quot;5.3.1 Anhänge von Kartenobjekten&quot;">​</a></h3><p>Zu jedem Kartenobjekt können Sie Dateien ablegen. Der Reiter „Anhänge“ steht deshalb bei allen Objektarten zur Verfügung. Hier können Sie Anhänge hinzufügen, herunterladen, umbenennen oder löschen.</p><p>Zum Hinzufügen klicken Sie im Bereich „Dateien hochladen“ auf „Dateien auswählen“ oder ziehen Sie die Datei auf die Fläche „Dateien auswählen oder hierher ziehen“. Die maximale Dateigröße beträgt 50 MB.</p><p>Vorhandene Dateien stehen darunter im Bereich „Hochgeladene Dateien“. Sind noch keine vorhanden, erscheint stattdessen „Keine Dateien hochgeladen“. Die Dateien sind in Ordnern zusammengefasst, die nach ihrer Art benannt sind und die Anzahl enthalten, z. B. „documents (1)“. Gehen Sie so vor:</p><ol><li>Klicken Sie auf den Ordner, um ihn aufzuklappen. Erst dann werden die einzelnen Dateien sichtbar.</li><li>Zeigen Sie mit der Maus auf eine Datei. Rechts neben dem Dateinamen erscheinen drei Symbolschaltflächen; ihre Tooltips lauten „Herunterladen“, „Umbenennen“ und „Datei löschen“.</li><li>Klicken Sie auf die gewünschte Schaltfläche. Beim Löschen bestätigen Sie die Rückfrage.</li></ol><p>Wichtig: Solange der Ordner zugeklappt ist, erscheinen die Symbolschaltflächen nicht.</p><p>Bei vielen Dateien hilft das Feld „Dateien suchen“ oberhalb der Liste. Sollten die Symbolschaltflächen nicht sichtbar sein, ist eventuell Ihr Fenster zu klein. Sie können in der Info-Box nach links und rechts scrollen oder die Box am linken Rand breiter ziehen.</p>',36),e("p",null,[e("video",{src:m,controls:"",playsinline:"",preload:"metadata"},[a(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/map_attachment.webm",download:""},"herunterladen"),a(" anstelle des Videos. ")])],-1),i('<h2 id="_5-4-suche" tabindex="-1">5.4 Suche <a class="header-anchor" href="#_5-4-suche" aria-label="Permalink to &quot;5.4 Suche&quot;">​</a></h2><p>Oben links befindet sich eine <strong>Suchfunktion</strong>. Hier können Sie gezielt nach Adressen, Netzknoten, Trassen, Rohren und Gebieten suchen.</p><p><img src="'+b+'" alt="Screenshot Karte mit Hervorhebung des Suchfeldes oben links" data-zoomable="true"></p><p>Dazu gehen Sie folgendermaßen vor:</p><ol><li>Geben Sie einen Begriff oder einen Teil davon in das Suchfeld ein.</li><li>Drücken Sie Enter oder klicken Sie auf das orange Lupen-Symbol.</li><li>Die Trefferliste öffnet sich direkt unterhalb des Suchfeldes. Links oben steht die Anzahl der Treffer.</li><li>Jeder Treffer ist in Großbuchstaben mit seiner Objektart gekennzeichnet, etwa „Adresse“, „Netzknoten“ oder „Trasse“.</li><li>Ab zehn Treffern erscheint im Kopf der Liste das Feld „Filtern“. Damit schränken Sie die Liste weiter ein; die Anzeige wechselt dann auf die Form „2 / 46“.</li><li>Klicken Sie auf einen Treffer. Die Karte springt an die passende Stelle, das Objekt blinkt dreimal auf und das Suchfeld wird geleert.</li></ol><p><img src="'+p+'" alt="Vier Screenshots des Suchablaufs in der Karte, nummeriert von 1 bis 6" data-zoomable="true"></p><p>Die Suche findet auch Teilbegriffe. Sie müssen also nicht die vollständige Bezeichnung kennen.</p><p>Sollten Sie sich Details zu diesem Objekt anzeigen lassen wollen, klicken Sie auf das Objekt in der Karte (siehe <a href="#_5-3-auswahl-von-objekten">Auswahl von Objekten</a>).</p>',8)])])}const v=t(k,[["render",f]]);export{D as __pageData,v as default};
